{
  "avaliacoes": [
    {
      "id": "Eb09f8ac2af6ec76e",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "Em FPSOs/FSUs, estabilidade, integridade estanque e manutenção de posição exigem controle rigoroso durante operações de carga, armazenamento e descarga de óleo cru.",
          "trechos": [
            "Eb09f8ac2af6ec76e:0:698",
            "Eb09f8ac2af6ec76e:698:1395"
          ],
          "condicoes": [
            "no contexto de embarcações monohull do tipo FPSO ou FSU",
            "durante operações de carregamento, armazenamento e descarga de óleo cru"
          ],
          "limites": [
            "a fonte é de jurisdição do Reino Unido/HSE, não estabelece requisito brasileiro",
            "o trecho não fornece parâmetros numéricos de controle nem procedimentos completos"
          ]
        },
        {
          "proposicao": "Tanques de óleo cru devem ser mantidos em condição que impeça a atmosfera interna de entrar na faixa explosiva, o que depende de controle rigoroso dos sistemas de inertização durante carga e descarga.",
          "trechos": [
            "Eb09f8ac2af6ec76e:698:1395"
          ],
          "condicoes": [
            "aplica-se a tanques de óleo cru em operações de loading e discharge",
            "inclui situações em que haja necessidade de preparação do tanque para entrada"
          ],
          "limites": [
            "a fonte não detalha setpoints, composição de gás inerte ou critérios de aceitação",
            "trata-se de orientação normativa/regulatória do documento citado"
          ]
        },
        {
          "proposicao": "A perda de posição de um FPSO/FSU pode levar a colisão com instalação adjacente ou liberação de hidrocarbonetos por fratura de risers de perfuração ou de operações de poço; por isso, o sistema de amarração e seus arranjos são tratados como elementos críticos de segurança.",
          "trechos": [
            "Eb09f8ac2af6ec76e:1395:2089",
            "Eb09f8ac2af6ec76e:2089:2185"
          ],
          "condicoes": [
            "no enquadramento de análise de perigos e safety case da instalação",
            "quando a manutenção de posição é relevante para proximidade de outras instalações ou integridade de risers"
          ],
          "limites": [
            "a classificação como SCE decorre do referencial HSE/safety case",
            "o trecho não apresenta critérios de desempenho, redundância ou inspeção do sistema de amarração"
          ]
        }
      ]
    },
    {
      "id": "E914a97fda0eef171",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "Em FPSOs/FSUs, pela frequência de carregamento e descarga ser maior que em petroleiros oceânicos em trânsito, torna-se ainda mais crítico executar essas operações conforme plano de estabilidade aprovado e segui-lo estritamente.",
          "trechos": [
            "E914a97fda0eef171:698:1397"
          ],
          "condicoes": [
            "na comparação entre operação de FPSO/FSU e de navio petroleiro convencional",
            "durante operações frequentes de carga e descarga, inclusive para navio aliviador"
          ],
          "limites": [
            "o documento reflete prática regulatória/operacional do Reino Unido",
            "o trecho não informa conteúdo mínimo do plano nem autoridade aprovadora aplicável em outras jurisdições"
          ]
        },
        {
          "proposicao": "Execução incorreta de procedimentos de carga ou descarga pode levar ao excedimento dos limites de momento fletor e/ou força cortante da embarcação e também colocar em risco sua estabilidade.",
          "trechos": [
            "E914a97fda0eef171:698:1397",
            "E914a97fda0eef171:1397:2097"
          ],
          "condicoes": [
            "quando procedimentos de discharge ou loading não são realizados corretamente"
          ],
          "limites": [
            "o trecho não fornece limites estruturais ou critérios de alarme/intertravamento",
            "não distingue consequências por configuração específica de casco ou operação"
          ]
        },
        {
          "proposicao": "O controle da estabilidade é atribuído à supervisão marinha/operação de lastro, com apoio de computador de carga ou estabilidade que registra conteúdos de tanques do casco e requer entrada manual de cargas de convés e outras variáveis para exibir estabilidade, momentos fletores e forças cortantes.",
          "trechos": [
            "E914a97fda0eef171:1397:2097",
            "E914a97fda0eef171:2097:2142"
          ],
          "condicoes": [
            "na operação da instalação com sistema computacional de estabilidade",
            "com atualização automática de conteúdos de tanques e intervenção manual para cargas de convés e variáveis não capturadas automaticamente"
          ],
          "limites": [
            "o trecho não descreve lógica de validação dos dados inseridos nem periodicidade de atualização",
            "não detalha como o sistema se integra a procedimentos de decisão operacional"
          ]
        }
      ]
    },
    {
      "id": "Ecdd73b63d4ea91e0",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Na operação de offloading, o óleo é exportado do FPSO ao navio aliviador por sistema de mangueiras flexíveis.",
          "trechos": [
            "Ecdd73b63d4ea91e0:0:696"
          ],
          "condicoes": [
            "na definição apresentada para operação de offloading entre FPSO e shuttle tanker"
          ],
          "limites": [
            "o trecho é terminológico/descritivo, não traz procedimento, capacidade nem critérios de segurança operacional"
          ]
        },
        {
          "proposicao": "A estação de offloading, localizada na proa ou popa, reúne equipamentos como carretel de mangueira, HPU e guinchos de hawser; FPSOs/FSOs spread moored são descritos com duas estações e unidades single point moored com uma.",
          "trechos": [
            "Ecdd73b63d4ea91e0:0:696"
          ],
          "condicoes": [
            "na descrição conceitual da arquitetura de exportação de óleo",
            "conforme a distinção entre spread moored e single point moored adotada pela fonte"
          ],
          "limites": [
            "a fonte não apresenta exceções de projeto nem generaliza explicitamente para toda instalação existente",
            "não informa critérios de seleção da posição da estação ou impactos sobre operação integrada"
          ]
        },
        {
          "proposicao": "O sistema de telemetria entre shuttle tanker e F(P)SO é descrito como meio automatizado de comunicação capaz de alertar ambas as partes em caso de mau funcionamento de equipamentos de offloading, incluindo válvulas, bombas e gás inerte.",
          "trechos": [
            "Ecdd73b63d4ea91e0:1391:2088"
          ],
          "condicoes": [
            "durante operações de transferência entre F(P)SO e shuttle tanker"
          ],
          "limites": [
            "o trecho não detalha arquitetura do sistema, confiabilidade, redundância ou ações automáticas decorrentes dos alertas",
            "não estabelece requisito normativo brasileiro"
          ]
        }
      ]
    },
    {
      "id": "E3132ede1edc4dcf7",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Sistemas permanentes de amarração são apresentados como desenvolvidos para garantir a estabilidade de estruturas flutuantes offshore.",
          "trechos": [
            "E3132ede1edc4dcf7:0:699"
          ],
          "condicoes": [
            "no contexto de estruturas flutuantes utilizadas em ambiente offshore"
          ],
          "limites": [
            "a fonte é descritiva e não define estabilidade em termos operacionais ou normativos detalhados",
            "a independência documental é indeterminada"
          ]
        },
        {
          "proposicao": "Entre os principais sistemas de amarração citados estão SPM, spread mooring e dynamic positioning; o spread mooring é associado a ambientes menos agressivos e o DP a plataformas com grandes offsets e pouco tempo de estadia, podendo atuar junto com outros sistemas de ancoragem.",
          "trechos": [
            "E3132ede1edc4dcf7:0:699",
            "E3132ede1edc4dcf7:699:1398"
          ],
          "condicoes": [
            "na classificação e caracterização apresentada pela fonte",
            "quanto ao DP, em unidades com grande deslocamento e curta permanência"
          ],
          "limites": [
            "a associação a certos ambientes e tempos de estadia é descritiva, não normativa",
            "o trecho não estabelece critérios formais de seleção, envelopes ambientais ou desempenho comparativo"
          ]
        },
        {
          "proposicao": "Na configuração convencional catenária, a linha de ancoragem possui trecho apoiado no leito marinho e transmite apenas esforços horizontais à fundação, o que condiciona a compatibilidade com âncoras adequadas a esse tipo de solicitação.",
          "trechos": [
            "E3132ede1edc4dcf7:1398:2088",
            "E3132ede1edc4dcf7:2088:2382"
          ],
          "condicoes": [
            "na configuração do tipo convencional/catenária"
          ],
          "limites": [
            "há número apagado sobre proporções geométricas, que não pode ser reconstruído",
            "o trecho não compara em profundidade com taut leg ou tendões verticais"
          ]
        }
      ]
    },
    {
      "id": "E14ef7e6fbdfc1f92",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Nos sistemas offshore, o conjunto tecnológico é descrito como composto por casco, linhas, equipamentos submarinos, poços e amarrações, indicando a necessidade de considerar interfaces entre subsistemas na operação integrada.",
          "trechos": [
            "E14ef7e6fbdfc1f92:0:692"
          ],
          "condicoes": [
            "na descrição geral do ambiente tecnológico offshore"
          ],
          "limites": [
            "o trecho é classificatório e não detalha mecanismos operacionais dessas interfaces",
            "a independência documental da fonte é indeterminada"
          ]
        },
        {
          "proposicao": "A comparação apresentada entre plataformas fixas e flutuantes associa às flutuantes a sustentação das cargas ambientais por inércia, estabilidade, empuxo e resistência de ancoragem, além de acesso ao poço por risers flexíveis.",
          "trechos": [
            "E14ef7e6fbdfc1f92:692:1379"
          ],
          "condicoes": [
            "na tabela comparativa entre plataformas fixas e flutuantes"
          ],
          "limites": [
            "a comparação é geral e não contempla exceções de projeto",
            "não fornece critérios quantitativos de dimensionamento ou operação"
          ]
        },
        {
          "proposicao": "Para FPSO, a fonte descreve três formas principais de ancoragem: single point mooring, spread mooring e turret.",
          "trechos": [
            "E14ef7e6fbdfc1f92:1379:2074",
            "E14ef7e6fbdfc1f92:2074:2352"
          ],
          "condicoes": [
            "na descrição das alternativas principais de ancoragem do FPSO"
          ],
          "limites": [
            "o trecho termina sem desenvolver o funcionamento do turret e sem discutir critérios de escolha",
            "não trata de impactos detalhados sobre risers, poços ou offloading"
          ]
        }
      ]
    },
    {
      "id": "E787663d0b887884c",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "A avaliação de integridade marítima indicada pelo documento depende da combinação de áreas aplicáveis de integridade e do julgamento profissional do inspetor para definir o ranqueamento global de risco da instalação.",
          "trechos": [
            "E787663d0b887884c:0:695",
            "E787663d0b887884c:695:1392"
          ],
          "condicoes": [
            "no contexto de inspeção e avaliação de maritime integrity"
          ],
          "limites": [
            "trata-se de abordagem de inspeção do HSE/Reino Unido, não de requisito brasileiro",
            "o trecho não explicita a ponderação entre áreas nem critérios fechados de pontuação"
          ]
        },
        {
          "proposicao": "O documento relaciona como áreas específicas de integridade marítima os sistemas de estabilidade e lastro, integridade estanque, sistemas de amarração, posicionamento dinâmico e operações de tanques de carga/offloading em FPSO.",
          "trechos": [
            "E787663d0b887884c:1392:2089",
            "E787663d0b887884c:2089:2428"
          ],
          "condicoes": [
            "na estrutura de apêndices usada para tratar a integridade marítima de instalações flutuantes"
          ],
          "limites": [
            "o trecho apenas enumera temas e referências correlatas",
            "não desenvolve critérios operacionais de cada sistema nessa seção"
          ]
        },
        {
          "proposicao": "Há referência específica a orientações sobre risco de inundação em espaços de máquinas de instalações flutuantes, incluindo válvulas de costado, detecção e controle de inundação, inspeção e treinamento.",
          "trechos": [
            "E787663d0b887884c:695:1392",
            "E787663d0b887884c:1392:2089"
          ],
          "condicoes": [
            "como referência adicional dentro do arcabouço de integridade marítima citado pelo documento"
          ],
          "limites": [
            "esta fonte apenas remete à orientação correlata, sem reproduzir seu conteúdo técnico",
            "não permite extrair procedimentos ou requisitos detalhados de controle de inundação"
          ]
        }
      ]
    }
  ],
